<?php
namespace App\Http\Controllers;
use App\Support\{MarketingSite,WebsiteSeo};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,DB};
use Illuminate\Validation\Rule;
class WebsiteSeoAdminController {
 public function index(){return view('platform.seo.index',['pages'=>DB::table('website_seo_pages')->orderBy('kind')->orderBy('id')->get(),'redirects'=>DB::table('website_seo_redirects')->orderBy('id')->get(),'settings'=>MarketingSite::settings()]);}
 public function edit(?int $id=null){$page=$id?DB::table('website_seo_pages')->find($id):null;abort_if($id&&!$page,404);return view('platform.seo.edit',compact('page'));}
 public function save(Request $r,?int $id=null){$old=$id?DB::table('website_seo_pages')->find($id):null;abort_if($id&&!$old,404);$v=$r->validate(['kind'=>['required',Rule::in(array_keys(WebsiteSeo::KINDS))],'slug'=>['required','max:120','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/',Rule::unique('website_seo_pages','slug')->where('kind',$r->input('kind'))->ignore($id)],'heading'=>'required|string|max:200','seo_title'=>'required|string|max:200','description'=>'required|string|max:500','intro'=>'required|string|max:2000','body'=>'required|string|max:30000','faq'=>'nullable|string|max:10000','social_title'=>'nullable|string|max:200','social_description'=>'nullable|string|max:500','social_image'=>['nullable','string','max:255','regex:~^/marketing/assets/[a-zA-Z0-9_-]+\.(?:png|jpg|jpeg|webp)$~'],'canonical'=>['nullable','url:https','max:255',function($a,$v,$fail){$base=WebsiteSeo::base(MarketingSite::settings());if(!str_starts_with($v,$base.'/') || str_contains($v,'?') || str_contains($v,'#'))$fail('Use a canonical URL on the public MentoClock domain without a query or fragment.');}],'published'=>'nullable|boolean','indexable'=>'nullable|boolean']);foreach(['faq','social_title','social_description','social_image','canonical'] as $field)$v[$field]=$v[$field]??null;if($v['social_image'] && !is_file(public_path(ltrim($v['social_image'],'/'))))return back()->withErrors(['social_image'=>'The selected image asset does not exist.'])->withInput();$v['published']=$r->boolean('published');$v['indexable']=$r->boolean('indexable');$v['updated_at']=now();$new='/'.$v['kind'].'/'.$v['slug']; if(DB::table('website_seo_redirects')->where('source',$new)->exists())return back()->withErrors(['slug'=>'This URL is reserved by a redirect. Remove that redirect first.'])->withInput();DB::transaction(function()use($id,$old,$v,$new){if($id){DB::table('website_seo_pages')->where('id',$id)->update($v);$before=WebsiteSeo::path($old);if($before!==$new){DB::table('website_seo_redirects')->where('destination',$before)->update(['destination'=>$new,'updated_at'=>now()]);DB::table('website_seo_redirects')->updateOrInsert(['source'=>$before],['destination'=>$new,'created_at'=>now(),'updated_at'=>now()]);}}else DB::table('website_seo_pages')->insert($v+['created_at'=>now()]);$this->audit('SEO page saved',['path'=>$new]);});return redirect('/platform/website/seo')->with('status','SEO page saved.');}
 public function settings(Request $r){$v=$r->validate(['seo_title'=>'required|string|max:200','seo_description'=>'required|string|max:500','seo_verification'=>['nullable','string','max:200','regex:/^[A-Za-z0-9_-]+$/'],'seo_social_title'=>'nullable|string|max:200','seo_social_description'=>'nullable|string|max:500']);DB::transaction(function()use($v){foreach($v as $k=>$value)DB::table('marketing_site_settings')->updateOrInsert(['key'=>$k],['value'=>$value??'','updated_at'=>now(),'created_at'=>now()]);$this->audit('SEO settings updated',[]);});return back()->with('status','SEO settings saved.');}
 public function redirectSave(Request $r){$pattern='~^/(features|industries|blog)/[a-z0-9]+(?:-[a-z0-9]+)*$~';$v=$r->validate(['source'=>['required','max:180','regex:'.$pattern],'destination'=>['required','max:180','different:source','regex:'.$pattern]]);[$a,$b]=explode('/',trim($v['source'],'/'));[$c,$d]=explode('/',trim($v['destination'],'/'));if(DB::table('website_seo_pages')->where('kind',$a)->where('slug',$b)->exists() || !DB::table('website_seo_pages')->where('kind',$c)->where('slug',$d)->where('published',true)->exists())return back()->withErrors(['source'=>'Source must be unused and destination must be a published SEO page.']);DB::transaction(function()use($v){DB::table('website_seo_redirects')->updateOrInsert(['source'=>$v['source']],['destination'=>$v['destination'],'created_at'=>now(),'updated_at'=>now()]);$this->audit('SEO redirect saved',$v);});return back()->with('status','Redirect saved.');}
 public function redirectDelete(int $id){DB::transaction(function()use($id){DB::table('website_seo_redirects')->where('id',$id)->delete();$this->audit('SEO redirect removed',['id'=>$id]);});return back()->with('status','Redirect removed.');}
 private function audit(string $action,array $details){DB::table('platform_audit_logs')->insert(['actor_id'=>Auth::guard('platform')->id(),'business_id'=>null,'action'=>$action,'details'=>json_encode($details,JSON_THROW_ON_ERROR),'created_at'=>now()]);}
}
